
@forelse($records as $record)<tr><td>{{ $record->name }}</td>@if(in_array($type, ['employees', 'technicians']))<td>{{ $record->email }}</td>@endif @if($type === 'employees')<td>{{ optional($record->department)->name }}</td><td>{{ $record->activation_pending ? 'For Activation' : ($record->trashed() ? 'Inactive' : 'Active') }}</td>@endif @if($type === 'services')<td>{{ strip_tags($record->content) }}</td>@endif @if($type === 'issues')<td>{{ optional($record->task)->name ?? 'Unavailable service' }}</td>@endif<td><a class="btn btn-secondary btn-sm icon-action" href="{{ route('dashboard.settings.edit', [$type, $record->id]) }}" aria-label="Edit {{ $record->name }}"><x-action-icon name="pencil-square" /></a></td></tr>@empty @unless($datatable ?? false)<tr><td colspan="{{ $type === 'employees' ? 5 : ($type === 'departments' ? 2 : 3) }}" class="empty-cell">No records found.</td></tr>@endunless @endforelse

